const body = $input.first().json.body || $input.first().json;
const channelUrl = (body.channelUrl || body.url || '').trim();
const rawKeywords = body.keywords || [];
const apiKey = (body.apiKey || '').trim();
const sheetId = (body.sheetId || '').trim();

if (!channelUrl) throw new Error('channelUrl is required');
if (!apiKey) throw new Error('apiKey (YouTube Data API key) is required');
if (!rawKeywords.length) throw new Error('keywords array must have at least one entry');

const keywords = rawKeywords.map(k => k.toLowerCase().trim()).filter(Boolean);

// Playlist detection — extract playlistId directly if present
let isPlaylist = false;
let playlistId = '';
if (channelUrl.includes('list=')) {
  isPlaylist = true;
  playlistId = channelUrl.split('list=')[1].split('&')[0];
}

// Channel handle / ID extraction
let handle = '';
let channelId = '';
if (!isPlaylist) {
  if (channelUrl.includes('/@')) {
    handle = channelUrl.split('/@')[1].split('/')[0].split('?')[0];
  } else if (channelUrl.includes('/channel/')) {
    channelId = channelUrl.split('/channel/')[1].split('/')[0].split('?')[0];
  } else if (channelUrl.includes('/c/')) {
    handle = channelUrl.split('/c/')[1].split('/')[0].split('?')[0];
  } else if (channelUrl.includes('/user/')) {
    handle = channelUrl.split('/user/')[1].split('/')[0].split('?')[0];
  } else {
    handle = channelUrl.replace(/https?:\/\/(www\.)?youtube\.com\//, '').replace('@', '').trim();
  }
}

// Load processed IDs from workflow static data (persists between runs)
const staticData = $getWorkflowStaticData('global');
const processedIds = staticData.processedIds || [];

// Store sheetId for later use in index-building nodes
if (sheetId) staticData.currentSheetId = sheetId;

return [{ json: { handle, channelId, keywords, apiKey, sheetId, isPlaylist, playlistId, processedIds } }];

const { handle, channelId, keywords, apiKey, sheetId, isPlaylist, playlistId, processedIds } = $input.first().json;

let uploadsPlaylistId;
let channelTitle;

if (isPlaylist) {
  // Direct playlist URL — get its title, use playlistId directly
  const params = new URLSearchParams({ part: 'snippet', id: playlistId, key: apiKey });
  const res = await $helpers.httpRequest({
    method: 'GET',
    url: `https://www.googleapis.com/youtube/v3/playlists?${params}`
  });
  channelTitle = res.items?.[0]?.snippet?.title || `Playlist ${playlistId}`;
  uploadsPlaylistId = playlistId;
} else {
  // Channel URL — look up the uploads playlist ID first
  const channelField = channelId ? { id: channelId } : { forHandle: handle };
  const params = new URLSearchParams({ part: 'contentDetails,snippet', ...channelField, key: apiKey });
  const channelRes = await $helpers.httpRequest({
    method: 'GET',
    url: `https://www.googleapis.com/youtube/v3/channels?${params}`
  });
  if (!channelRes.items?.length) throw new Error(`Channel not found: "${handle || channelId}". Check the URL format.`);
  channelTitle = channelRes.items[0].snippet?.title || handle;
  uploadsPlaylistId = channelRes.items[0].contentDetails.relatedPlaylists.uploads;
}

// Paginate through ALL videos (up to 1000)
let allVideos = [];
let pageToken = '';
let pageCount = 0;
const MAX_PAGES = 20;

do {
  const params = new URLSearchParams({
    part: 'snippet',
    playlistId: uploadsPlaylistId,
    maxResults: '50',
    key: apiKey
  });
  if (pageToken) params.set('pageToken', pageToken);
  const res = await $helpers.httpRequest({
    method: 'GET',
    url: `https://www.googleapis.com/youtube/v3/playlistItems?${params}`
  });
  allVideos = allVideos.concat(res.items || []);
  pageToken = res.nextPageToken || '';
  pageCount++;
} while (pageToken && pageCount < MAX_PAGES);

return [{ json: { allVideos, keywords, apiKey, sheetId, channelTitle, totalVideos: allVideos.length, processedIds } }];

const { allVideos, keywords, apiKey, sheetId, channelTitle, totalVideos, processedIds } = $input.first().json;
const processedSet = new Set(processedIds);

// Step 1: keyword match on title + description
const keywordMatched = allVideos.filter(item => {
  const title = (item.snippet?.title || '').toLowerCase();
  const desc = (item.snippet?.description || '').toLowerCase();
  return keywords.some(kw => (title + ' ' + desc).includes(kw));
});

// Step 2: remove already-processed videos
const newVideos = keywordMatched.filter(item =>
  !processedSet.has(item.snippet?.resourceId?.videoId)
);

const alreadySavedCount = keywordMatched.length - newVideos.length;

if (newVideos.length === 0) {
  if (keywordMatched.length > 0) {
    throw new Error(`All ${keywordMatched.length} matching videos are already saved — nothing new to process.`);
  }
  throw new Error(`No videos matched keywords [${keywords.join(', ')}] out of ${totalVideos} total on "${channelTitle}". Try broader keywords.`);
}

return newVideos.map(item => ({
  json: {
    videoId: item.snippet.resourceId.videoId,
    title: item.snippet.title,
    publishedAt: item.snippet.publishedAt,
    apiKey,
    sheetId,
    channelTitle,
    matchedCount: keywordMatched.length,
    newCount: newVideos.length,
    alreadySavedCount,
    totalVideos
  }
}));

// Runs once for ALL matched videos, fetches each transcript with a preview summary
const allItems = $input.all();
const results = [];

for (const item of allItems) {
  const { videoId, title, channelTitle, publishedAt, sheetId } = item.json;

  await new Promise(resolve => setTimeout(resolve, 600));

  let transcriptText = '';
  let preview = '';
  let skipped = false;

  try {
    const res = await $helpers.httpRequest({
      method: 'GET',
      url: `https://www.youtube.com/api/timedtext?lang=en&v=${videoId}&fmt=json3`
    });

    const events = (res.events || []);

    if (events.length === 0) {
      skipped = true;
      transcriptText = 'No English transcript available for this video.';
      preview = 'No transcript available.';
    } else {
      const lines = [];
      for (const event of events) {
        if (!event.segs) continue;
        const text = event.segs.map(s => s.utf8 || '').join('').trim().replace(/\n/g, ' ');
        if (text) lines.push(text);
      }

      const paragraphs = [];
      for (let i = 0; i < lines.length; i += 8) {
        paragraphs.push(lines.slice(i, i + 8).join(' '));
      }

      // Free summary: first 2-3 sentences of the transcript
      const firstPara = paragraphs[0] || '';
      const sentences = firstPara.match(/[^.!?]+[.!?]+/g) || [];
      preview = sentences.slice(0, 3).join(' ').trim() || firstPara.substring(0, 250);

      transcriptText = paragraphs.join('\n\n');
    }
  } catch (err) {
    skipped = true;
    transcriptText = `Error fetching transcript: ${err.message}`;
    preview = 'Transcript fetch failed.';
  }

  const publishDate = (publishedAt || '').substring(0, 10) || 'unknown';
  const safeTitle = title.replace(/[^a-zA-Z0-9 _-]/g, '').replace(/\s+/g, '_').substring(0, 60);
  const fileName = `${safeTitle}_${videoId}.txt`;

  const fileContent = [
    `Title: ${title}`,
    `Channel: ${channelTitle}`,
    `Published: ${publishedAt || 'unknown'}`,
    `Video: https://www.youtube.com/watch?v=${videoId}`,
    '',
    `Preview: ${preview}`,
    '',
    '---',
    '',
    transcriptText
  ].join('\n');

  results.push({
    json: { fileName, fileContent, title, videoId, channelTitle, publishedAt, preview, sheetId, skipped }
  });
}

return results;

// Mark this video as processed in persistent static data so future scans skip it
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedIds) staticData.processedIds = [];
const videoId = $json.videoId;
if (videoId && !staticData.processedIds.includes(videoId)) {
  staticData.processedIds.push(videoId);
}
return [$input.item];
